//! 🧪️ The original erased cancellation and close orders retain the same issued owners.
use super::*;

enum Mode{Cut(usize),AuthorityFirst,ReadFirst}

fn case(copy:usize,text:&str,mode:Mode,stock:&serde_json::Value){
 let(value,initial)=semio_framework_value_testing_allocator::observe_retirement_allocations(||text.to_owned());assert_eq!(initial.1,0);let mut bank=source_bank::Bank::from_stock(&stock["stock"],false);let mut recipient=NativeDecodeRetirementRecipient::new();let mut observer=|_|true;let mut native=NativeDecodeControl::new(stock["stock"]["capacityBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut frame=NativeReceivingEffect::default();
 let mut actor=OriginalEffectAuthority::new(IssueProducer{birth:ManuallyDrop::new(ReadRegistryBirth::new()),issued:ManuallyDrop::new(None),authority:ManuallyDrop::new(None),aliases:ManuallyDrop::new(std::array::from_fn(|_|None)),value:Some(value),inputs:ManuallyDrop::new(std::array::from_fn(|_|None)),stored:ManuallyDrop::new(std::array::from_fn(|_|None)),root:ManuallyDrop::new(None),issue:ManuallyDrop::new(None),lease:ManuallyDrop::new(None),visit:ManuallyDrop::new(None),erased:ManuallyDrop::new(None),root_close:ManuallyDrop::new(None),typed_source:ManuallyDrop::new(None),typed_owner:ManuallyDrop::new(Default::default()),typed_action:None,typed_reply:ManuallyDrop::new(None),wrong_reply:ManuallyDrop::new(None),source:ManuallyDrop::new(None),owner:ManuallyDrop::new(Default::default()),owner_action:None,owner_reply:ManuallyDrop::new(None),cursor:ManuallyDrop::new(None),cursor_reply:ManuallyDrop::new(None),turn:bank.turn.identity()});
 for _ in 0..65536{if actor.inspect(|p|p.birth.ready()){break}sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::Birth);}assert!(actor.inspect(|p|p.birth.ready()));sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::Take);sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::Authority);sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::Root);
 let address=actor.inspect(|p|p.root.as_ref().unwrap().get()as*const String as usize);sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::IssueBirth);for _ in 0..16{if actor.inspect(|p|p.lease.is_some()){break}sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::Issue);}assert_eq!(actor.inspect(|p|p.lease.as_ref().unwrap().get()as*const String as usize),address);sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::IssueReturn);sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::IssueClear);
 sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::EraseShort(1));sparse::turn_with_copy(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::Erase,Some(copy));assert!(actor.inspect(|p|p.erased.is_none()&&p.lease.as_ref().unwrap().get()as*const String as usize==address));sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::Erase);
 actor.inspect(|p|{let read=p.erased.as_ref().unwrap();assert_eq!(read.get::<String>().unwrap()as*const String as usize,address);assert!(read.get::<u64>().is_none());assert_eq!(serde_json::to_value(read.get::<String>().unwrap()).unwrap(),text)});
 if matches!(mode,Mode::AuthorityFirst){close_authority(&mut bank,&mut native,&mut frame,&mut actor);actor.inspect(|p|{let read=p.erased.as_ref().unwrap();assert_eq!(read.get::<String>().unwrap()as*const String as usize,address);assert_eq!(read.get::<String>().unwrap().as_str(),text)})}
 if let Mode::Cut(cut)=mode{for _ in 0..cut{if actor.inspect(|p|p.erased.as_ref().unwrap().terminal_is_empty()){break}close_read_once(&mut bank,&mut native,&mut frame,&mut actor);}}
 for _ in 0..65536{if actor.inspect(|p|p.erased.as_ref().unwrap().terminal_is_empty()){break}close_read_once(&mut bank,&mut native,&mut frame,&mut actor);}assert!(actor.inspect(|p|p.erased.as_ref().unwrap().terminal_is_empty()));sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::ErasedClear);
 if !matches!(mode,Mode::AuthorityFirst){close_authority(&mut bank,&mut native,&mut frame,&mut actor)}
 assert!(actor.inspect(IssueProducer::terminal));drop(actor.into_producer().ok().unwrap());let wallet=bank.wallet.lock().unwrap();assert_eq!(wallet.spent.released_bytes,wallet.spent.retained_capacity_bytes+initial.0);
}

fn close_read_once(bank:&mut source_bank::Bank,native:&mut NativeDecodeControl<'_>,frame:&mut NativeReceivingEffect<OriginalRetirementFailure>,actor:&mut OriginalEffectAuthority<IssueProducer<String>>){let original=actor.inspect(|p|ErasedSnapshotRetirement::requires_original_control(p.erased.as_ref().unwrap()));sparse::turn(bank,native,frame,actor,if original{IssueOp::ErasedOriginal}else{IssueOp::ErasedClose});}
fn close_authority(bank:&mut source_bank::Bank,native:&mut NativeDecodeControl<'_>,frame:&mut NativeReceivingEffect<OriginalRetirementFailure>,actor:&mut OriginalEffectAuthority<IssueProducer<String>>){for _ in 0..65536{if actor.inspect(|p|p.authority.as_ref().unwrap().terminal_is_empty()){break}let original=actor.inspect(|p|p.authority.as_ref().unwrap().requires_original_control());sparse::turn(bank,native,frame,actor,if original{IssueOp::AuthorityOriginal}else{IssueOp::AuthorityClose});}assert!(actor.inspect(|p|p.authority.as_ref().unwrap().terminal_is_empty()));sparse::turn(bank,native,frame,actor,IssueOp::AuthorityClear);}

pub(crate) fn run_erased_cancellation(){let law:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("../../🧬️schema/🔣️.json")).unwrap();assert_eq!(schema["const"],law);let stock:serde_json::Value=serde_json::from_str(include_str!("../../🎟️work/case.json")).unwrap();for copy in law["workBytes"].as_array().unwrap(){for cut in law["erasedCancelAt"].as_array().unwrap(){case(copy.as_u64().unwrap()as usize,law["erasedCancellationRoot"].as_str().unwrap(),Mode::Cut(cut.as_u64().unwrap()as usize),&stock)}}}
pub(crate) fn run_close_orders(){let law:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("../../🧬️schema/🔣️.json")).unwrap();assert_eq!(schema["const"],law);let stock:serde_json::Value=serde_json::from_str(include_str!("../../🎟️work/case.json")).unwrap();for copy in law["workBytes"].as_array().unwrap(){for order in law["closeOrders"].as_array().unwrap(){let mode=match order.as_str().unwrap(){"read-first"=>Mode::ReadFirst,"authority-first"=>Mode::AuthorityFirst,_=>panic!("unknown original close order")};case(copy.as_u64().unwrap()as usize,law["closeOrderRoot"].as_str().unwrap(),mode,&stock)}}}

